 import React, { useEffect, useState } from 'react';
import axios from 'axios';

function AdminBlockedUsers() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState('');

  const fetchUsers = async () => {
    try {
      const response = await axios.get('http://localhost:8080/users', {
        headers: {
          Authorization: `Bearer ${localStorage.getItem('token')}`
        }
      });
      setUsers(response.data);
    } catch (err) {
      console.error('Eroare la obținerea utilizatorilor:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleBlock = async (userId) => {
    try {
      await axios.put(`http://localhost:8080/users/block/${userId}`, {}, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem('token')}`
        }
      });
      setMessage(`Utilizatorul cu ID ${userId} a fost blocat.`);
      fetchUsers();
    } catch (err) {
      console.error('Eroare la blocare:', err);
    }
  };

  const handleUnblock = async (userId) => {
    try {
      await axios.put(`http://localhost:8080/users/unblock/${userId}`, {}, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem('token')}`
        }
      });
      setMessage(`Utilizatorul cu ID ${userId} a fost deblocat.`);
      fetchUsers();
    } catch (err) {
      console.error('Eroare la deblocare:', err);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  return (
    <div style={{ padding: '2rem' }}>
      <h2>Toți utilizatorii</h2>
      {loading ? (
        <p>Se încarcă...</p>
      ) : users.length === 0 ? (
        <p>Nu există utilizatori înregistrați.</p>
      ) : (
        <table>
          <thead>
            <tr>
              <th>ID</th>
              <th>Username</th>
              <th>Email</th>
              <th>Status</th>
              <th>Acțiune</th>
            </tr>
          </thead>
          <tbody>
            {users.map((user) => (
              <tr key={user.id}>
                <td>{user.id}</td>
                <td>{user.username}</td>
                <td>{user.email}</td>
                <td>{user.blocked ? 'Blocat' : 'Activ'}</td>
                <td>
                  {user.blocked ? (
                    <button onClick={() => handleUnblock(user.id)}>
                      Deblochează
                    </button>
                  ) : (
                    <button onClick={() => handleBlock(user.id)}>
                      Blochează
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
      {message && <p style={{ color: 'green' }}>{message}</p>}
    </div>
  );
}

export default AdminBlockedUsers;
